actor RateLimiter {
  private let clock = ContinuousClock()
  private var tokens: Double, last: ContinuousClock.Instant
  private let rate: Double, burst: Double
  init(rate: Double, burst: Double) {
    self.rate = rate; self.burst = burst; self.tokens = burst; self.last = clock.now }
  func acquire(_ cost: Double = 1) -> Bool {
    let now = clock.now, e = now - last
    tokens = min(tokens + rate * (Double(e.components.seconds) + Double(e.components.attoseconds) * 1e-18), burst)
    last = now
    guard tokens >= cost else { return false }     // caller: 429 / await sleep
    tokens -= cost; return true
  }
}

